// The unguarded scan `main.ts` calls, in a dependency outside the program's
// no-panic scope; `main.ts`'s header says why it is refused. The
// `i <= 2147483631` bound only keeps `i += 16` inside `i32`, so the load is
// the one site that may panic.
import { bitmask, eq, loadU8x16, splatU8x16 } from "nish:simd"

export const newlineMask = (xs: u8[]): i32 => {
  const newline = splatU8x16(10)
  let mask: i32 = 0
  let i: i32 = 0
  while (i >= 0 && i < toI32(xs.length) && i <= 2147483631) {
    mask = mask ^ bitmask(eq(loadU8x16(xs, i), newline))
    i += 16
  }
  return mask
}
